package cn.jingyu.deepseek;
import org.json.*;import java.util.*;

/** Keep generated documents available when a reply is regenerated or a chat is deleted. */
final class GeneratedCatalog {
 static void add(JSONObject state,JSONObject file,String title){ChatSession.put(file,"chatTitle",title);if(!file.has("createdAt"))ChatSession.put(file,"createdAt",System.currentTimeMillis());JSONArray all=state.optJSONArray("generatedFiles");if(all==null){all=new JSONArray();ChatSession.put(state,"generatedFiles",all);}for(int i=0;i<all.length();i++)if(all.optJSONObject(i)!=null&&all.optJSONObject(i).optString("id").equals(file.optString("id")))return;all.put(file);}
 static void remove(JSONObject state,String id){JSONArray catalog=state.optJSONArray("generatedFiles");removeFrom(catalog,id);JSONArray chats=state.optJSONArray("chats");for(int i=0;chats!=null&&i<chats.length();i++){JSONObject chat=chats.optJSONObject(i);JSONArray messages=chat==null?null:chat.optJSONArray("messages");for(int j=0;messages!=null&&j<messages.length();j++){JSONObject message=messages.optJSONObject(j);if(message!=null)removeFrom(message.optJSONArray("artifacts"),id);}}}
 static void removeFrom(JSONArray files,String id){for(int i=files==null?-1:files.length()-1;i>=0;i--){JSONObject file=files.optJSONObject(i);if(file!=null&&file.optString("id").equals(id))files.remove(i);}}
 static JSONArray all(JSONObject state){JSONArray result=new JSONArray();Set<String> ids=new HashSet<>();JSONArray catalog=state.optJSONArray("generatedFiles");for(int i=catalog==null?-1:catalog.length()-1;i>=0;i--){JSONObject file=catalog.optJSONObject(i);if(file!=null&&ids.add(file.optString("id")))result.put(file);}JSONArray chats=state.optJSONArray("chats");for(int i=chats==null?-1:chats.length()-1;i>=0;i--){JSONObject chat=chats.optJSONObject(i);JSONArray messages=chat==null?null:chat.optJSONArray("messages");for(int j=messages==null?-1:messages.length()-1;j>=0;j--){JSONObject message=messages.optJSONObject(j);JSONArray files=message==null?null:message.optJSONArray("artifacts");for(int k=files==null?-1:files.length()-1;k>=0;k--){JSONObject file=files.optJSONObject(k);if(file!=null&&ids.add(file.optString("id"))){ChatSession.put(file,"chatTitle",chat.optString("title"));result.put(file);}}}}return result;}
}
